mapper.select:
SELECT al.id, al.operator_id, COALESCE(NULLIF(u.nickname, ''), NULLIF(u.username, ''), u.phone, '系统任务') AS operator_name, al.operation_type, al.biz_type, al.biz_id, al.content, al.request_ip, al.user_agent, al.create_time, al.create_by, al.update_by FROM audit_log al LEFT JOIN sys_user u ON u.id = al.operator_id AND u.deleted = 0 WHERE al.deleted = 0
AND al.operator_id = #{operatorId}
AND al.operation_type = #{operationType}
AND al.biz_type = #{bizType}
AND al.biz_id = #{bizId}
AND al.create_time >= #{dateFrom}
AND al.create_time <= #{dateTo}
AND ( al.content LIKE CONCAT('%', #{keyword}, '%') OR al.operation_type LIKE CONCAT('%', #{keyword}, '%') OR al.biz_type LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(u.username, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(u.phone, '') LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY al.create_time DESC, al.id DESC
